\version "2.27.2"
% automatically converted by musicxml2ly from 02c-Rests-MultiMeasureRests.xml
\pointAndClickOff

\header {
  texidoc = "Five multi-measure rests: 3 measures, 15 measures, 1 measure,
    12 measures, and finally 3 measures with the ‘use-symbols’ attribute set."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
    \override MultiMeasureRest.expand-limit = 1
  }
  \context {
    \Score
    skipBars = ##t
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative c' {
  \clef "treble" \time 4/4 \key c \major R1*3 | % 3
  R1*15 | % 18
  R1 | % 19

  \barNumberCheck #20
  R1*12 | % 31
  \tweak expand-limit 10 R1*3 \bar "|."
}


% The score definition
